package io.tenvyr.control.engine;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import io.tenvyr.platform.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.apache.kafka.clients.consumer.*;
import org.apache.kafka.clients.producer.*;
import org.apache.kafka.common.TopicPartition;
import org.apache.kafka.common.errors.WakeupException;
import org.apache.kafka.common.serialization.*;

/** Retained runtime-v1 Kafka identities; poison records are acknowledged, durable failures redeliver. */
public final class KafkaAgentAdapter implements AgentAdapter {
  private final AgentTransportConfig config;private final ExecutionService executions;private final Map<String,String> env;private final Set<String> eventTopics=new HashSet<>();private volatile Handlers handlers;private volatile boolean started,idle,stopping;private KafkaProducer<String,String> producer;private KafkaConsumer<String,String> consumer;private Thread polling;
  public KafkaAgentAdapter(AgentTransportConfig config,ExecutionService executions){this(config,executions,System.getenv());}
  public KafkaAgentAdapter(AgentTransportConfig config,ExecutionService executions,Map<String,String> env){this.config=config;this.executions=executions;this.env=Map.copyOf(env);}
  public String kind(){return "kafka";}
  public synchronized void start(Handlers handlers){if(started)return;this.handlers=handlers;boolean explicit=!env.getOrDefault("ORCHESTRATOR_EVENT_TOPICS","").isBlank()||!env.getOrDefault("ORCHESTRATOR_RESULT_TOPICS","").isBlank();if(!config.hasKafkaAgents()&&!explicit){idle=true;started=true;return;}String brokers=env.getOrDefault("KAFKA_BROKERS","localhost:9092"),clientId=env.getOrDefault("KAFKA_CLIENT_ID","agentweave-orchestrator");Properties p=new Properties();p.put("bootstrap.servers",brokers);p.put("client.id",clientId);p.put("key.serializer",StringSerializer.class.getName());p.put("value.serializer",StringSerializer.class.getName());producer=new KafkaProducer<>(p);Properties c=new Properties();c.put("bootstrap.servers",brokers);c.put("client.id",clientId);c.put("group.id","agentweave-orchestrator-group");c.put("enable.auto.commit",false);c.put("auto.offset.reset","latest");c.put("key.deserializer",StringDeserializer.class.getName());c.put("value.deserializer",StringDeserializer.class.getName());consumer=new KafkaConsumer<>(c);Set<String> topics=new LinkedHashSet<>();for(String agent:split(env.getOrDefault("ORCHESTRATOR_AGENT_NAMES","code-reviewer,observability"))){topics.add("agentweave.agent."+agent+".result");eventTopics.add("agentweave.agent."+agent+".event");}topics.addAll(split(env.getOrDefault("ORCHESTRATOR_RESULT_TOPICS","")));eventTopics.addAll(split(env.getOrDefault("ORCHESTRATOR_EVENT_TOPICS","")));topics.addAll(eventTopics);consumer.subscribe(topics);stopping=false;started=true;polling=new Thread(this::poll,"tenvyr-kafka-results");polling.setDaemon(true);polling.start();}
  private void poll(){try{while(!stopping){ConsumerRecords<String,String> records=consumer.poll(Duration.ofSeconds(1));for(TopicPartition partition:records.partitions()){for(ConsumerRecord<String,String> record:records.records(partition)){try{processMessage(record.topic(),record.partition(),record.offset(),record.timestamp(),record.key(),record.value());consumer.commitSync(Map.of(partition,new OffsetAndMetadata(record.offset()+1)));}catch(AdapterError error){if(error.retryable){consumer.seek(partition,record.offset());break;}throw error;}}}}}catch(WakeupException e){if(!stopping)System.err.println("Kafka consumer interrupted");}catch(RuntimeException e){if(!stopping)System.err.println("Kafka consumer failed: "+e.getClass().getSimpleName());}finally{consumer.close(Duration.ofSeconds(5));}}
  public ObjectNode invoke(ObjectNode invocation,ObjectNode pinned)throws Exception{if(idle)throw new AdapterError("KAFKA_TRANSPORT_IDLE",false,"No Kafka agents are configured");if(!started)throw new AdapterError("ADAPTER_NOT_STARTED",true,"Kafka adapter not started");ObjectNode payload=Protocol.invocation(invocation);try{producer.send(new ProducerRecord<>("agentweave.agent."+payload.path("target").path("agent").asText()+".task",payload.path("executionId").asText(),Json.stringify(payload))).get();}catch(Exception e){throw new AdapterError("DISPATCH_FAILED",true,"Kafka invocation dispatch failed",0,e);}return Json.object("adapter","kafka","invocationId",payload.path("invocationId"),"dispatchedAt",Protocol.jsInstant(Instant.now()),"messageKey",payload.path("executionId"));}
  /** Returns normally for permanent poison; only retryable handler/database failures escape. */
  public void processMessage(String topic,int partition,long offset,long timestamp,String key,String raw)throws AdapterError {if(raw==null)return;ObjectNode transport=Json.object("adapter","kafka","receivedAt",Protocol.jsInstant(Instant.now()),"messageKey",key,"topic",topic,"partition",partition,"offset",Long.toString(offset));JsonNode payload;try{payload=Json.parse(raw);}catch(Exception poison){return;}if(eventTopics.contains(topic)){ObjectNode event;try{event=Protocol.event(payload);}catch(IllegalArgumentException poison){return;}try{if(handlers==null)throw new IllegalStateException("Handler unavailable");handlers.event(event,transport);}catch(Exception error){if(error instanceof AgentEventService.PayloadTooLarge)return;throw new AdapterError("EVENT_HANDLER_FAILED",true,"Agent event handler failed",0,error);}return;}
    ObjectNode result;try{result=normalizeResult(payload,timestamp);}catch(IllegalArgumentException poison){return;}catch(RuntimeException infrastructure){throw new AdapterError("RESULT_HANDLER_FAILED",true,"Legacy result context lookup failed",0,infrastructure);}if(result==null)return;try{if(handlers==null)throw new IllegalStateException("Handler unavailable");handlers.result(result,transport);}catch(Exception error){throw new AdapterError("RESULT_HANDLER_FAILED",true,"Agent result handler failed",0,error);}
  }
  private ObjectNode normalizeResult(JsonNode payload,long timestamp){if("1".equals(Json.text(payload,"schemaVersion")))return Protocol.result(payload);String executionId=Json.text(payload,"executionId"),stepId=Json.text(payload,"stepId");if(executionId==null||executionId.isEmpty()||stepId==null||stepId.isEmpty())throw new IllegalArgumentException("Legacy result missing correlation");ObjectNode step=executions.getStepExecution(executionId,stepId);if(step==null)return null;int attempt=payload.path("attempt").isNumber()?payload.path("attempt").asInt():step.path("attempt").asInt();String completed=payload.path("timestamp").isTextual()&&!payload.path("timestamp").asText().isEmpty()?payload.path("timestamp").asText():Protocol.jsInstant(Instant.ofEpochMilli(timestamp));return Protocol.normalizeResult(payload,Json.object("invocationId",step.path("id").asText()+":"+attempt,"executionId",executionId,"stepExecutionId",step.path("id"),"completedAt",completed));}
  public void addEventTopicForTest(String topic){eventTopics.add(topic);}
  private static List<String> split(String raw){return Arrays.stream(raw.split(",")).map(String::trim).filter(s->!s.isEmpty()).toList();}
  public synchronized void close()throws Exception{if(!started)return;stopping=true;if(consumer!=null){consumer.wakeup();if(polling!=null)polling.join(6000);}if(producer!=null)producer.close(Duration.ofSeconds(5));started=false;idle=false;handlers=null;eventTopics.clear();}
}
